class PrStatus(BaseModel):
    """The state of a pull request and its checks."""
    repo: str
    number: int

@tool(PrStatus, effect="read")
async def pr_status(req: PrStatus, ctx) -> dict:
    return await gh_json("pr", "view", req.number, "-R", req.repo, "--json", "state,statusCheckRollup")
